#!/bin/sh
# Build PS5 Backup Center: engine (pbc-engine2.elf), TV app (eboot.bin), then the app folder out/PPSA99950/
# and out/PPSA99950.zip. Licence: GPL-3.0-or-later (LICENSE).
#
# Requirements (not included):
#   SDK              the free PS5 payload SDK (https://github.com/ps5-payload-dev/sdk)
#   LLVM             LLVM 18 bin directory (clang-18, ld.lld)
#   PS5_NATIVE_TOOL  ELF -> eboot.bin linker/signer (ps5-native-app-boilerplate, tooling/native)
set -e
cd "$(dirname "$0")"
ROOT=$(pwd)
: "${SDK:?set SDK}" "${LLVM:?set LLVM}" "${PS5_NATIVE_TOOL:?set PS5_NATIVE_TOOL}"
OUT=${OUT:-$ROOT/out}
VERSION=$(sed -n 's/.*"version": *"\([^"]*\)".*/\1/p' app/package/PPSA99950/version.json | head -1)
mkdir -p "$OUT/app" "$OUT/app/obj" "$OUT/engine" "$OUT/engine/obj"
python3 engine/tools/embed_web.py
"$LLVM/clang-18" -target x86_64-sie-ps5 -fvisibility-nodllstorageclass=default -isysroot "$SDK" -isystem "$SDK/target/include/c++/v1" -isystem "$SDK/target/include" -fno-stack-protector -fno-plt -O2 -Wall -Wextra -Werror -DPBCK_PS5=1 "-ffile-prefix-map=$ROOT/=" -std=c++20 -femulated-tls -femulated-tls -fno-exceptions -fno-rtti -I engine/src -I engine/third_party -I engine/third_party/zlib -I engine/third_party/stb -I engine/third_party/sqlite -I engine/third_party/bearssl/inc -I engine/third_party/libwebp -I engine/third_party/libsmb2/include "-DPBC_VERSION=\"$VERSION\"" '-DPBC_UPDATE_URL="https://consolecenterstudio.github.io/ps5-backup-center/updates/latest.json"' -DZ_SOLO -c engine/src/accounts/accounts.cpp -o "$OUT/engine/obj/engine__src__accounts__accounts.o"
"$LLVM/clang-18" -target x86_64-sie-ps5 -fvisibility-nodllstorageclass=default -isysroot "$SDK" -isystem "$SDK/target/include/c++/v1" -isystem "$SDK/target/include" -fno-stack-protector -fno-plt -O2 -Wall -Wextra -Werror -DPBCK_PS5=1 "-ffile-prefix-map=$ROOT/=" -std=c++20 -femulated-tls -femulated-tls -fno-exceptions -fno-rtti -I engine/src -I engine/third_party -I engine/third_party/zlib -I engine/third_party/stb -I engine/third_party/sqlite -I engine/third_party/bearssl/inc -I engine/third_party/libwebp -I engine/third_party/libsmb2/include "-DPBC_VERSION=\"$VERSION\"" '-DPBC_UPDATE_URL="https://consolecenterstudio.github.io/ps5-backup-center/updates/latest.json"' -DZ_SOLO -c engine/src/accounts/identities.cpp -o "$OUT/engine/obj/engine__src__accounts__identities.o"
